sc_cat_item_producer.script:
(function () {

    // ---- Read producer variables ----
    var hospital = ('' + producer.hospital_name).trim();
    var city = producer.city;
    var address = producer.address;
    var phone = producer.phone;
    var email = producer.email;
    var admin = producer.admin;
    var hold_hours = producer.hold_hours_planned;
    var emergency_hours = producer.hold_hours_emergency;
    var blocks = parseInt(producer.block_count, 10) || 0;
    var floors = parseInt(producer.floor_count_per_block, 10) || 0;

    // Temporary debug line - remove once everything works
    gs.info('PRODUCER DEBUG: hospital=[' + hospital + '] blocks=' + blocks + ' floors=' + floors);

    if (!hospital || hospital === 'undefined') {
        gs.error('Hospital producer: hospital_name variable is empty or the variable name is wrong.');
        return;
    }

    // ---- Top-level location (the hospital) ----
    var gr = new GlideRecord('cmn_location');
    gr.initialize();
    gr.name = hospital;
    gr.city = city;
    gr.phone = phone;
    var loc_id = gr.insert();

    if (!loc_id) {
        gs.error('Hospital producer: location insert failed: ' + gr.getLastErrorMessage());
        return;
    }

    // ---- Blocks and floors ----
    for (var i = 1; i <= blocks; i++) {

        var gr2 = new GlideRecord('cmn_location');
        gr2.initialize();
        gr2.name = 'Block ' + i;
        gr2.city = city;
        gr2.phone = phone;
        gr2.parent = loc_id;
        var block_id = gr2.insert();

        if (!block_id) {
            gs.error('Hospital producer: Block ' + i + ' insert failed: ' + gr2.getLastErrorMessage());
            continue;
        }

        for (var j = 1; j <= floors; j++) {

            var gr3 = new GlideRecord('cmn_location');
            gr3.initialize();
            gr3.name = 'Block ' + i + ' Floor ' + j;
            gr3.city = city;
            gr3.phone = phone;
            gr3.parent = block_id;
            var floor_id = gr3.insert();   // this insert was missing

            if (!floor_id) {
                gs.error('Hospital producer: Block ' + i + ' Floor ' + j + ' insert failed: ' + gr3.getLastErrorMessage());
            }
        }
    }

    // ---- Hospital record on the custom table ----
    var hos_record = new GlideRecord('x_2223823_apollo_0_hospital');
    hos_record.initialize();
    hos_record.setValue('name', hospital);   // confirm 'name' is the real column name in the dictionary
    hos_record.city = city;
    hos_record.address = address;
    hos_record.hold_hours_planned = hold_hours;
    hos_record.hold_hours_emergency = emergency_hours;
    hos_record.hospital_administrator = admin;
    hos_record.phone = phone;
    hos_record.email = email;
    hos_record.parent = loc_id;
    var hos_id = hos_record.insert();

    if (!hos_id) {
        gs.error('Hospital producer: hospital record insert failed: ' + hos_record.getLastErrorMessage());
    }

})();
